  "nodes": {
    "Component": [
      {
        "component_id": "comp_bleed_type_master_air_valve",
        "name": "Bleed-type master air valve",
        "description": "Air-line valve that relieves trapped air between the valve and the air motor when closed.",
        "category": "air-line accessory"
      },
      {
        "component_id": "comp_fluid_drain_valve",
        "name": "Fluid drain valve",
        "description": "Fluid-line valve used to relieve fluid pressure in the displacement pump, hose, and gun.",
        "category": "fluid-line accessory"
      },
      {
        "component_id": "comp_pump_runaway_valve",
        "name": "Pump runaway valve",
        "description": "Air-line accessory that senses when the pump is running too fast and automatically shuts off air to the motor.",
        "category": "air-line accessory"
      },
      {
        "component_id": "comp_air_line_lubricator",
        "name": "Air line lubricator",
        "description": "Provides automatic lubrication to the air motor.",
        "category": "air-line accessory"
      },
      {
        "component_id": "comp_air_regulator",
        "name": "Air regulator",
        "description": "Controls pump speed and outlet pressure by adjusting air pressure to the pump.",
        "category": "air-line accessory"
      },
      {
        "component_id": "comp_air_line_filter",
        "name": "Air line filter",
        "description": "Removes dirt and moisture from the compressed air supply.",
        "category": "air-line accessory"
      },
      {
        "component_id": "comp_air_line_isolation_valve",
        "name": "Second bleed-type air valve",
        "description": "Isolates the air-line accessories for servicing.",
        "category": "air-line accessory"
      },
      {
        "component_id": "comp_air_motor",
        "name": "Air motor",
        "description": "Motor supplied with air through the air-line accessories.",
        "category": "motor"
      },
      {
        "component_id": "comp_air_and_fluid_hoses",
        "name": "Air and fluid hoses",
        "description": "Hoses supplying air and conveying fluid; the manual specifies sizing, pressure-rating, and grounding requirements.",
        "category": "lines"
      },
      {
        "component_id": "comp_air_line_quick_disconnect_coupler",
        "name": "Air line quick disconnect coupler",
        "description": "Coupler connecting the air hose to the air manifold on pumps mounted on the pneumatic elevator cart.",
        "category": "air-line accessory"
      },
      {
        "component_id": "comp_fluid_regulator",
        "name": "Fluid regulator",
        "description": "Controls fluid pressure to the gun or valve and dampens pressure surges.",
        "category": "fluid-line accessory"
      },
      {
        "component_id": "comp_dispensing_gun_or_valve",
        "name": "Gun or valve",
        "description": "Dispenses the fluid.",
        "category": "fluid dispensing"
      },
      {
        "component_id": "comp_gun_swivel",
        "name": "Gun swivel",
        "description": "Allows freer gun movement.",
        "category": "fluid dispensing"
      },
      {
        "component_id": "comp_wiper_plate",
        "name": "Wiper plate",
        "description": "Used with the pump when it is mounted on a pneumatic elevator cart or pail ram.",
        "category": "fluid handling"
      },
      {
        "component_id": "comp_pneumatic_elevator_cart",
        "name": "Pneumatic elevator cart",
        "description": "A mounting option for the pump.",
        "category": "mounting equipment"
      },
      {
        "component_id": "comp_pail_ram",
        "name": "Pail ram",
        "description": "An alternative mounting arrangement for the pump, used with a wiper plate.",
        "category": "mounting equipment"
      },
      {
        "component_id": "comp_air_compressor",
        "name": "Air compressor",
        "description": "Air supply equipment referenced in the grounding instructions.",
        "category": "air supply"
      }
